57	  public void testDefaults() {
58	    MapMakerInternalMap<Object, Object, ?, ?> map = makeMap(createMapMaker());
59	
60	    assertThat(map.keyStrength()).isEqualTo(Strength.STRONG);
61	    assertThat(map.valueStrength()).isEqualTo(Strength.STRONG);
62	    assertThat(map.keyEquivalence).isEqualTo(map.keyStrength().defaultEquivalence());
63	    assertThat(map.valueEquivalence()).isEqualTo(map.valueStrength().defaultEquivalence());
64	
65	    assertThat(map.entryHelper)
66	        .isInstanceOf(MapMakerInternalMap.StrongKeyStrongValueEntry.Helper.class);
67	
68	    assertEquals(4, map.concurrencyLevel);
69	
70	    // concurrency level
