183	  public void testNewEntry() {
184	    for (MapMaker maker : allWeakValueStrengthMakers()) {
185	      MapMakerInternalMap<Object, Object, ?, ?> map = makeMap(maker);
186	      Segment<Object, Object, ?, ?> segment = map.segments[0];
187	
188	      Object keyOne = new Object();
189	      Object valueOne = new Object();
190	      int hashOne = map.hash(keyOne);
191	      InternalEntry<Object, Object, ?> entryOne = segment.newEntryForTesting(keyOne, hashOne, null);
192	      WeakValueReference<Object, Object, ?> valueRefOne =
193	          segment.newWeakValueReferenceForTesting(entryOne, valueOne);
194	      assertThat(valueRefOne.get()).isEqualTo(valueOne);
195	      segment.setWeakValueReferenceForTesting(entryOne, valueRefOne);
196	
197	      assertThat(entryOne.getKey()).isEqualTo(keyOne);
198	      assertEquals(hashOne, entryOne.getHash());
199	      assertThat(entryOne.getNext()).isNull();
200	      assertThat(segment.getWeakValueReferenceForTesting(entryOne)).isEqualTo(valueRefOne);
201	
202	      Object keyTwo = new Object();
203	      Object valueTwo = new Object();
204	      int hashTwo = map.hash(keyTwo);
205	
206	      InternalEntry<Object, Object, ?> entryTwo =
207	          segment.newEntryForTesting(keyTwo, hashTwo, entryOne);
208	      WeakValueReference<Object, Object, ?> valueRefTwo =
209	          segment.newWeakValueReferenceForTesting(entryTwo, valueTwo);
210	      assertThat(valueRefTwo.get()).isEqualTo(valueTwo);
211	      segment.setWeakValueReferenceForTesting(entryTwo, valueRefTwo);
212	
213	      assertThat(entryTwo.getKey()).isEqualTo(keyTwo);
214	      assertEquals(hashTwo, entryTwo.getHash());
215	      assertThat(entryTwo.getNext()).isEqualTo(entryOne);
216	      assertThat(segment.getWeakValueReferenceForTesting(entryTwo)).isEqualTo(valueRefTwo);
217	    }
218	  }
