220	  public void testCopyEntry() {
221	    for (MapMaker maker : allWeakValueStrengthMakers()) {
222	      MapMakerInternalMap<Object, Object, ?, ?> map = makeMap(maker);
223	      Segment<Object, Object, ?, ?> segment = map.segments[0];
