227	      int hashOne = map.hash(keyOne);
228	      InternalEntry<Object, Object, ?> entryOne = segment.newEntryForTesting(keyOne, hashOne, null);
229	      segment.setValueForTesting(entryOne, valueOne);
230	
231	      Object keyTwo = new Object();
232	      Object valueTwo = new Object();
233	      int hashTwo = map.hash(keyTwo);
234	      InternalEntry<Object, Object, ?> entryTwo = segment.newEntryForTesting(keyTwo, hashTwo, null);
235	      segment.setValueForTesting(entryTwo, valueTwo);
236	
237	      InternalEntry<Object, Object, ?> copyOne = segment.copyForTesting(entryOne, null);
238	      assertThat(entryOne.getKey()).isEqualTo(keyOne);
239	      assertEquals(hashOne, entryOne.getHash());
240	      assertThat(entryOne.getNext()).isNull();
241	      assertThat(copyOne.getValue()).isEqualTo(valueOne);
242	
243	      InternalEntry<Object, Object, ?> copyTwo = segment.copyForTesting(entryTwo, copyOne);
244	      assertThat(copyTwo.getKey()).isEqualTo(keyTwo);
245	      assertEquals(hashTwo, copyTwo.getHash());
246	      assertThat(copyTwo.getNext()).isEqualTo(copyOne);
247	      assertThat(copyTwo.getValue()).isEqualTo(valueTwo);
248	    }
