251	  public void testSegmentGetAndContains() {
252	    MapMakerInternalMap<Object, Object, ?, ?> map =
253	        makeMap(createMapMaker().concurrencyLevel(1).weakValues());
254	    Segment<Object, Object, ?, ?> segment = map.segments[0];
255	    // TODO(fry): check recency ordering
256	
257	    Object key = new Object();
258	    int hash = map.hash(key);
259	    Object value = new Object();
260	    AtomicReferenceArray<? extends InternalEntry<Object, Object, ?>> table = segment.table;
261	    int index = hash & (table.length() - 1);
262	
263	    InternalEntry<Object, Object, ?> entry = segment.newEntryForTesting(key, hash, null);
264	    segment.setValueForTesting(entry, value);
265	
266	    assertThat(segment.get(key, hash)).isNull();
267	
268	    // count == 0
269	    segment.setTableEntryForTesting(index, entry);
270	    assertThat(segment.get(key, hash)).isNull();
271	    assertFalse(segment.containsKey(key, hash));
272	    assertFalse(segment.containsValue(value));
273	
274	    // count == 1
275	    incrementCount(segment);
276	    assertThat(segment.get(key, hash)).isEqualTo(value);
277	    assertTrue(segment.containsKey(key, hash));
278	    assertTrue(segment.containsValue(value));
279	    // don't see absent values now that count > 0
280	    assertThat(segment.get(new Object(), hash)).isNull();
281	
282	    // null key
283	    InternalEntry<Object, Object, ?> nullEntry = segment.newEntryForTesting(null, hash, entry);
284	    Object nullValue = new Object();
285	    WeakValueReference<Object, Object, ?> nullValueRef =
286	        segment.newWeakValueReferenceForTesting(nullEntry, nullValue);
287	    segment.setWeakValueReferenceForTesting(nullEntry, nullValueRef);
288	    segment.setTableEntryForTesting(index, nullEntry);
289	    // skip the null key
290	    assertThat(segment.get(key, hash)).isEqualTo(value);
291	    assertTrue(segment.containsKey(key, hash));
292	    assertTrue(segment.containsValue(value));
293	    assertFalse(segment.containsValue(nullValue));
294	
295	    // hash collision
296	    InternalEntry<Object, Object, ?> dummyEntry =
297	        segment.newEntryForTesting(new Object(), hash, entry);
298	    Object dummyValue = new Object();
299	    WeakValueReference<Object, Object, ?> dummyValueRef =
300	        segment.newWeakValueReferenceForTesting(dummyEntry, dummyValue);
301	    segment.setWeakValueReferenceForTesting(dummyEntry, dummyValueRef);
302	    segment.setTableEntryForTesting(index, dummyEntry);
303	    assertThat(segment.get(key, hash)).isEqualTo(value);
304	    assertTrue(segment.containsKey(key, hash));
305	    assertTrue(segment.containsValue(value));
306	    assertTrue(segment.containsValue(dummyValue));
307	
308	    // key collision
309	    dummyEntry = segment.newEntryForTesting(key, hash, entry);
310	    dummyValue = new Object();
311	    dummyValueRef = segment.newWeakValueReferenceForTesting(dummyEntry, dummyValue);
312	    segment.setWeakValueReferenceForTesting(dummyEntry, dummyValueRef);
313	    segment.setTableEntryForTesting(index, dummyEntry);
314	    // returns the most recent entry
315	    assertThat(segment.get(key, hash)).isEqualTo(dummyValue);
316	    assertTrue(segment.containsKey(key, hash));
317	    assertTrue(segment.containsValue(value));
318	    assertTrue(segment.containsValue(dummyValue));
319	  }
