321	  public void testSegmentReplaceValue() {
322	    MapMakerInternalMap<Object, Object, ?, ?> map =
323	        makeMap(createMapMaker().concurrencyLevel(1).weakValues());
324	    Segment<Object, Object, ?, ?> segment = map.segments[0];
325	    // TODO(fry): check recency ordering
326	
327	    Object key = new Object();
328	    int hash = map.hash(key);
329	    Object oldValue = new Object();
330	    Object newValue = new Object();
331	    AtomicReferenceArray<? extends InternalEntry<Object, Object, ?>> table = segment.table;
332	    int index = hash & (table.length() - 1);
333	
334	    InternalEntry<Object, Object, ?> entry = segment.newEntryForTesting(key, hash, null);
335	    WeakValueReference<Object, Object, ?> oldValueRef =
336	        segment.newWeakValueReferenceForTesting(entry, oldValue);
337	    segment.setWeakValueReferenceForTesting(entry, oldValueRef);
338	
339	    // no entry
340	    assertFalse(segment.replace(key, hash, oldValue, newValue));
341	    assertEquals(0, segment.count);
342	
343	    // same value
344	    segment.setTableEntryForTesting(index, entry);
345	    incrementCount(segment);
346	    assertEquals(1, segment.count);
347	    assertThat(segment.get(key, hash)).isEqualTo(oldValue);
348	    assertTrue(segment.replace(key, hash, oldValue, newValue));
349	    assertEquals(1, segment.count);
350	    assertThat(segment.get(key, hash)).isEqualTo(newValue);
351	
352	    // different value
353	    assertFalse(segment.replace(key, hash, oldValue, newValue));
354	    assertEquals(1, segment.count);
355	    assertThat(segment.get(key, hash)).isEqualTo(newValue);
356	
357	    // cleared
358	    segment.setWeakValueReferenceForTesting(entry, oldValueRef);
359	    oldValueRef.clear();
360	    assertFalse(segment.replace(key, hash, oldValue, newValue));
361	    assertEquals(0, segment.count);
362	    assertThat(segment.get(key, hash)).isNull();
363	  }
