513	    assertEquals(0, segment.count);
514	    assertThat(segment.get(key, hash)).isNull();
515	
516	    // cleared
517	    segment.setTableEntryForTesting(index, entry);
518	    incrementCount(segment);
519	    assertEquals(1, segment.count);
520	    assertThat(segment.get(key, hash)).isEqualTo(oldValue);
521	    oldValueRef.clear();
522	    assertThat(segment.remove(key, hash)).isNull();
523	    assertEquals(0, segment.count);
524	    assertThat(segment.get(key, hash)).isNull();
525	  }
