612	  public void testRemoveFromChain() {
613	    MapMakerInternalMap<Object, Object, ?, ?> map = makeMap(createMapMaker().concurrencyLevel(1));
614	    Segment<Object, Object, ?, ?> segment = map.segments[0];
615	
616	    // create 3 objects and chain them together
617	    Object keyOne = new Object();
618	    Object valueOne = new Object();
619	    int hashOne = map.hash(keyOne);
620	    InternalEntry<Object, Object, ?> entryOne = segment.newEntryForTesting(keyOne, hashOne, null);
621	    segment.setValueForTesting(entryOne, valueOne);
622	    Object keyTwo = new Object();
623	    Object valueTwo = new Object();
624	    int hashTwo = map.hash(keyTwo);
625	    InternalEntry<Object, Object, ?> entryTwo =
626	        segment.newEntryForTesting(keyTwo, hashTwo, entryOne);
627	    segment.setValueForTesting(entryTwo, valueTwo);
628	    Object keyThree = new Object();
629	    Object valueThree = new Object();
630	    int hashThree = map.hash(keyThree);
631	    InternalEntry<Object, Object, ?> entryThree =
632	        segment.newEntryForTesting(keyThree, hashThree, entryTwo);
633	    segment.setValueForTesting(entryThree, valueThree);
634	
635	    // alone
636	    assertThat(segment.removeFromChainForTesting(entryOne, entryOne)).isNull();
637	
638	    // head
639	    assertThat(segment.removeFromChainForTesting(entryTwo, entryTwo)).isEqualTo(entryOne);
640	
641	    // middle
642	    InternalEntry<Object, Object, ?> newFirst =
643	        segment.removeFromChainForTesting(entryThree, entryTwo);
644	    assertThat(newFirst.getKey()).isEqualTo(keyThree);
645	    assertThat(newFirst.getValue()).isEqualTo(valueThree);
646	    assertEquals(hashThree, newFirst.getHash());
647	    assertThat(newFirst.getNext()).isEqualTo(entryOne);
648	
649	    // tail (remaining entries are copied in reverse order)
650	    newFirst = segment.removeFromChainForTesting(entryThree, entryOne);
651	    assertThat(newFirst.getKey()).isEqualTo(keyTwo);
652	    assertThat(newFirst.getValue()).isEqualTo(valueTwo);
653	    assertEquals(hashTwo, newFirst.getHash());
654	    newFirst = newFirst.getNext();
655	    assertThat(newFirst.getKey()).isEqualTo(keyThree);
656	    assertThat(newFirst.getValue()).isEqualTo(valueThree);
657	    assertEquals(hashThree, newFirst.getHash());
658	    assertThat(newFirst.getNext()).isNull();
659	  }
