661	  @SuppressWarnings("GuardedBy")
662	  public void testExpand_cleanup() {
663	    MapMakerInternalMap<Object, Object, ?, ?> map =
664	        makeMap(createMapMaker().concurrencyLevel(1).initialCapacity(1));
665	    Segment<Object, Object, ?, ?> segment = map.segments[0];
666	    assertEquals(1, segment.table.length());
667	
668	    // manually add elements to avoid expansion
669	    // 1/3 null keys, 1/3 null values
670	    int originalCount = 1024;
671	    InternalEntry<Object, Object, ?> entry = null;
672	    for (int i = 0; i < originalCount; i++) {
673	      Object key = new Object();
674	      Object value = (i % 3 == 0) ? null : new Object();
675	      int hash = map.hash(key);
676	      if (i % 3 == 1) {
677	        key = null;
678	      }
679	      // chain all entries together as we only have a single bucket
680	      entry = segment.newEntryForTesting(key, hash, entry);
681	      segment.setValueForTesting(entry, value);
682	    }
683	    segment.setTableEntryForTesting(0, entry);
684	    segment.count = originalCount;
685	    int liveCount = originalCount / 3;
686	    assertEquals(1, segment.table.length());
687	    assertEquals(liveCount, countLiveEntries(map));
688	    ImmutableMap<Object, Object> originalMap = ImmutableMap.copyOf(map);
689	    assertEquals(liveCount, originalMap.size());
690	    // can't compare map contents until cleanup occurs
691	
692	    for (int i = 1; i <= originalCount * 2; i *= 2) {
693	      if (i > 1) {
694	        // TODO(b/145386688): This access should be guarded by 'segment', which is not currently
695	        // held
696	        segment.expand();
697	      }
698	      assertEquals(i, segment.table.length());
699	      assertEquals(liveCount, countLiveEntries(map));
700	      // expansion cleanup is sloppy, with a goal of avoiding unnecessary copies
701	      assertThat(segment.count).isAtLeast(liveCount);
702	      assertThat(segment.count).isAtMost(originalCount);
703	      assertEquals(originalMap, ImmutableMap.copyOf(map));
704	    }
705	  }
