707	  private static <K, V> int countLiveEntries(MapMakerInternalMap<K, V, ?, ?> map) {
708	    int result = 0;
709	    for (Segment<K, V, ?, ?> segment : map.segments) {
710	      AtomicReferenceArray<? extends InternalEntry<K, V, ?>> table = segment.table;
711	      for (int i = 0; i < table.length(); i++) {
712	        for (InternalEntry<K, V, ?> e = table.get(i); e != null; e = e.getNext()) {
713	          if (map.isLiveForTesting(e)) {
714	            result++;
715	          }
716	        }
717	      }
718	    }
719	    return result;
720	  }
