47	/**
48	 * A collection of utilities for {@link Cache} testing.
49	 *
50	 * @author mike nonemacher
51	 */
52	@GwtIncompatible
53	@J2ktIncompatible
54	@SuppressWarnings("GuardedBy") // TODO(b/35466881): Fix or suppress.
55	@NullUnmarked
56	final class CacheTesting {
57	
58	  /**
59	   * Poke into the Cache internals to simulate garbage collection of the value associated with the
60	   * given key. This assumes that the associated entry is a WeakValueReference or a
61	   * SoftValueReference (and not a LoadingValueReference), and throws an IllegalStateException if
62	   * that assumption does not hold.
63	   */
64	  @SuppressWarnings("unchecked") // the instanceof check and the cast generate this warning
65	  static <K, V> void simulateValueReclamation(Cache<K, V> cache, K key) {
66	    ReferenceEntry<K, V> entry = getReferenceEntry(cache, key);
67	    if (entry != null) {
68	      ValueReference<K, V> valueRef = entry.getValueReference();
69	      // fail on strong/computing refs
70	      Preconditions.checkState(valueRef instanceof Reference);
71	      Reference<V> ref = (Reference<V>) valueRef;
72	      if (ref != null) {
73	        ref.clear();
74	      }
75	    }
76	  }
77	
78	  /**
79	   * Poke into the Cache internals to simulate garbage collection of the given key. This assumes
80	   * that the given entry is a weak or soft reference, and throws an IllegalStateException if that
81	   * assumption does not hold.
82	   */
83	  static <K, V> void simulateKeyReclamation(Cache<K, V> cache, K key) {
84	    ReferenceEntry<K, V> entry = getReferenceEntry(cache, key);
85	
86	    Preconditions.checkState(entry instanceof Reference);
87	    Reference<?> ref = (Reference<?>) entry;
88	    if (ref != null) {
89	      ref.clear();
90	    }
91	  }
92	
93	  static <K, V> ReferenceEntry<K, V> getReferenceEntry(Cache<K, V> cache, K key) {
94	    checkNotNull(cache);
95	    checkNotNull(key);
96	    LocalCache<K, V> map = toLocalCache(cache);
97	    return map.getEntry(key);
98	  }
99	
100	  /**
101	   * Forces the segment containing the given {@code key} to expand (see {@link Segment#expand()}).
102	   */
103	  static <K, V> void forceExpandSegment(Cache<K, V> cache, K key) {
104	    checkNotNull(cache);
105	    checkNotNull(key);
106	    LocalCache<K, V> map = toLocalCache(cache);
107	    int hash = map.hash(key);
108	    Segment<K, V> segment = map.segmentFor(hash);
109	    segment.expand();
110	  }
111	
112	  /**
113	   * Gets the {@link LocalCache} used by the given {@link Cache}, if any, or throws an
114	   * IllegalArgumentException if this is a Cache type that doesn't have a LocalCache.
115	   */
116	  static <K, V> LocalCache<K, V> toLocalCache(Cache<K, V> cache) {
117	    if (cache instanceof LocalLoadingCache) {
118	      return ((LocalLoadingCache<K, V>) cache).localCache;
119	    }
120	    throw new IllegalArgumentException(
121	        "Cache of type " + cache.getClass() + " doesn't have a LocalCache.");
122	  }
123	
124	  /**
125	   * Determines whether the given cache can be converted to a LocalCache by {@link #toLocalCache}
126	   * without throwing an exception.
127	   */
128	  static boolean hasLocalCache(Cache<?, ?> cache) {
129	    return checkNotNull(cache) instanceof LocalLoadingCache;
130	  }
131	
132	  static void drainRecencyQueues(Cache<?, ?> cache) {
133	    if (hasLocalCache(cache)) {
134	      LocalCache<?, ?> map = toLocalCache(cache);
135	      for (Segment<?, ?> segment : map.segments) {
136	        drainRecencyQueue(segment);
137	      }
138	    }
139	  }
140	
141	  static void drainRecencyQueue(Segment<?, ?> segment) {
142	    segment.lock();
143	    try {
144	      segment.cleanUp();
145	    } finally {
146	      segment.unlock();
147	    }
148	  }
149	
150	  static void drainReferenceQueues(Cache<?, ?> cache) {
151	    if (hasLocalCache(cache)) {
152	      drainReferenceQueues(toLocalCache(cache));
153	    }
154	  }
155	
156	  static void drainReferenceQueues(LocalCache<?, ?> cchm) {
157	    for (LocalCache.Segment<?, ?> segment : cchm.segments) {
158	      drainReferenceQueue(segment);
159	    }
160	  }
161	
162	  static void drainReferenceQueue(LocalCache.Segment<?, ?> segment) {
163	    segment.lock();
164	    try {
165	      segment.drainReferenceQueues();
166	    } finally {
167	      segment.unlock();
168	    }
169	  }
170	
171	  static long getTotalSegmentSize(Cache<?, ?> cache) {
172	    LocalCache<?, ?> map = toLocalCache(cache);
173	    long totalSize = 0;
174	    for (Segment<?, ?> segment : map.segments) {
175	      totalSize += segment.maxSegmentWeight;
176	    }
177	    return totalSize;
178	  }
179	
180	  /**
181	   * Peeks into the cache's internals to check its internal consistency. Verifies that each
182	   * segment's count matches its #elements (after cleanup), each segment is unlocked, each entry
183	   * contains a non-null key and value, and the eviction and expiration queues are consistent (see
184	   * {@link #checkEviction}, {@link #checkExpiration}).
185	   */
186	  static void checkValidState(Cache<?, ?> cache) {
187	    if (hasLocalCache(cache)) {
188	      checkValidState(toLocalCache(cache));
189	    }
190	  }
191	
192	  static void checkValidState(LocalCache<?, ?> cchm) {
193	    for (Segment<?, ?> segment : cchm.segments) {
194	      segment.cleanUp();
195	      assertThat(segment.isLocked()).isFalse();
196	      Map<?, ?> table = segmentTable(segment);
197	      // cleanup and then check count after we have a strong reference to all entries
198	      segment.cleanUp();
199	      // under high memory pressure keys/values may be nulled out but not yet enqueued
200	      assertThat(table.size()).isAtMost(segment.count);
201	      for (Entry<?, ?> entry : table.entrySet()) {
202	        assertThat(entry.getKey()).isNotNull();
203	        assertThat(entry.getValue()).isNotNull();
204	        assertThat(cchm.get(entry.getKey())).isSameInstanceAs(entry.getValue());
205	      }
206	    }
207	    checkEviction(cchm);
208	    checkExpiration(cchm);
209	  }
210	
211	  /**
212	   * Peeks into the cache's internals to verify that its expiration queue is consistent. Verifies
213	   * that the next/prev links in the expiration queue are correct, and that the queue is ordered by
214	   * expiration time.
215	   */
216	  static void checkExpiration(Cache<?, ?> cache) {
217	    if (hasLocalCache(cache)) {
218	      checkExpiration(toLocalCache(cache));
219	    }
220	  }
221	
222	  static void checkExpiration(LocalCache<?, ?> cchm) {
223	    for (Segment<?, ?> segment : cchm.segments) {
224	      if (cchm.usesWriteQueue()) {
225	        Set<ReferenceEntry<?, ?>> entries = newIdentityHashSet();
226	
227	        ReferenceEntry<?, ?> prev = null;
228	        for (ReferenceEntry<?, ?> current : segment.writeQueue) {
229	          assertThat(entries.add(current)).isTrue();
230	          if (prev != null) {
231	            assertThat(current.getPreviousInWriteQueue()).isSameInstanceAs(prev);
232	            assertThat(current).isSameInstanceAs(prev.getNextInWriteQueue());
233	            assertThat(prev.getWriteTime()).isAtMost(current.getWriteTime());
234	          }
235	          Object key = current.getKey();
236	          if (key != null) {
237	            assertThat(segment.getEntry(key, current.getHash())).isSameInstanceAs(current);
238	          }
239	          prev = current;
240	        }
241	        assertThat(entries).hasSize(segment.count);
242	      } else {
243	        assertThat(segment.writeQueue.isEmpty()).isTrue();
244	      }
245	
246	      if (cchm.usesAccessQueue()) {
247	        Set<ReferenceEntry<?, ?>> entries = newIdentityHashSet();
248	
249	        ReferenceEntry<?, ?> prev = null;
250	        for (ReferenceEntry<?, ?> current : segment.accessQueue) {
251	          assertThat(entries.add(current)).isTrue();
252	          if (prev != null) {
253	            assertThat(current.getPreviousInAccessQueue()).isSameInstanceAs(prev);
254	            assertThat(current).isSameInstanceAs(prev.getNextInAccessQueue());
255	            // read accesses may be slightly misordered
256	            assertThat(
257	                    prev.getAccessTime() <= current.getAccessTime()
258	                        || prev.getAccessTime() - current.getAccessTime() < 1000)
259	                .isTrue();
260	          }
261	          Object key = current.getKey();
262	          if (key != null) {
263	            assertThat(segment.getEntry(key, current.getHash())).isSameInstanceAs(current);
264	          }
265	          prev = current;
266	        }
267	        assertThat(entries).hasSize(segment.count);
268	      } else {
269	        assertThat(segment.accessQueue).isEmpty();
270	      }
271	    }
272	  }
273	
274	  /**
275	   * Peeks into the cache's internals to verify that its eviction queue is consistent. Verifies that
276	   * the prev/next links are correct, and that all items in each segment are also in that segment's
277	   * eviction (recency) queue.
278	   */
279	  static void checkEviction(Cache<?, ?> cache) {
280	    if (hasLocalCache(cache)) {
281	      checkEviction(toLocalCache(cache));
282	    }
283	  }
284	
285	  static void checkEviction(LocalCache<?, ?> map) {
286	    if (map.evictsBySize()) {
287	      for (Segment<?, ?> segment : map.segments) {
288	        drainRecencyQueue(segment);
289	        assertThat(segment.recencyQueue).isEmpty();
290	        assertThat(segment.readCount.get()).isEqualTo(0);
291	
292	        ReferenceEntry<?, ?> prev = null;
293	        for (ReferenceEntry<?, ?> current : segment.accessQueue) {
294	          if (prev != null) {
295	            assertThat(current.getPreviousInAccessQueue()).isSameInstanceAs(prev);
296	            assertThat(current).isSameInstanceAs(prev.getNextInAccessQueue());
297	          }
298	          Object key = current.getKey();
299	          if (key != null) {
300	            assertThat(segment.getEntry(key, current.getHash())).isSameInstanceAs(current);
301	          }
302	          prev = current;
303	        }
304	      }
305	    } else {
306	      for (Segment<?, ?> segment : map.segments) {
307	        assertThat(segment.recencyQueue).isEmpty();
308	      }
309	    }
310	  }
311	
312	  static int segmentSize(Segment<?, ?> segment) {
313	    Map<?, ?> map = segmentTable(segment);
314	    return map.size();
315	  }
316	
317	  static <K, V> Map<K, V> segmentTable(Segment<K, V> segment) {
318	    AtomicReferenceArray<? extends ReferenceEntry<K, V>> table = segment.table;
319	    Map<K, V> map = new LinkedHashMap<>();
320	    for (int i = 0; i < table.length(); i++) {
321	      for (ReferenceEntry<K, V> entry = table.get(i); entry != null; entry = entry.getNext()) {
322	        K key = entry.getKey();
323	        V value = entry.getValueReference().get();
324	        if (key != null && value != null) {
325	          assertThat(map.put(key, value)).isNull();
326	        }
327	      }
328	    }
329	    return map;
330	  }
331	
332	  static int writeQueueSize(Cache<?, ?> cache) {
333	    LocalCache<?, ?> cchm = toLocalCache(cache);
334	
335	    int size = 0;
336	    for (Segment<?, ?> segment : cchm.segments) {
337	      size += writeQueueSize(segment);
338	    }
339	    return size;
340	  }
341	
342	  static int writeQueueSize(Segment<?, ?> segment) {
343	    return segment.writeQueue.size();
344	  }
345	
346	  static int accessQueueSize(Cache<?, ?> cache) {
347	    LocalCache<?, ?> cchm = toLocalCache(cache);
348	    int size = 0;
349	    for (Segment<?, ?> segment : cchm.segments) {
350	      size += accessQueueSize(segment);
351	    }
352	    return size;
353	  }
354	
355	  static int accessQueueSize(Segment<?, ?> segment) {
356	    return segment.accessQueue.size();
357	  }
358	
359	  static int expirationQueueSize(Cache<?, ?> cache) {
360	    return max(accessQueueSize(cache), writeQueueSize(cache));
361	  }
362	
363	  static void processPendingNotifications(Cache<?, ?> cache) {
364	    if (hasLocalCache(cache)) {
365	      LocalCache<?, ?> cchm = toLocalCache(cache);
366	      cchm.processPendingNotifications();
367	    }
368	  }
369	
370	  interface Receiver<T> {
371	    void accept(@Nullable T object);
372	  }
373	
374	  /**
375	   * Assuming the given cache has maximum size {@code maxSize}, this method populates the cache (by
376	   * getting a bunch of different keys), then makes sure all the items in the cache are also in the
377	   * eviction queue. It will invoke the given {@code operation} on the first element in the eviction
378	   * queue, and then reverify that all items in the cache are in the eviction queue, and verify that
379	   * the head of the eviction queue has changed as a result of the operation.
380	   */
381	  static void checkRecency(
382	      LoadingCache<Integer, Integer> cache,
383	      int maxSize,
384	      Receiver<ReferenceEntry<Integer, Integer>> operation) {
385	    checkNotNull(operation);
386	    if (hasLocalCache(cache)) {
387	      warmUp(cache, 0, 2 * maxSize);
388	
389	      LocalCache<Integer, Integer> cchm = toLocalCache(cache);
390	      Segment<?, ?> segment = cchm.segments[0];
391	      drainRecencyQueue(segment);
392	      assertThat(accessQueueSize(cache)).isEqualTo(maxSize);
393	      assertThat(cache.size()).isEqualTo(maxSize);
394	
395	      ReferenceEntry<?, ?> originalHead = segment.accessQueue.peek();
396	      @SuppressWarnings("unchecked")
397	      ReferenceEntry<Integer, Integer> entry = (ReferenceEntry<Integer, Integer>) originalHead;
398	      operation.accept(entry);
399	      drainRecencyQueue(segment);
400	
401	      assertThat(segment.accessQueue.peek()).isNotSameInstanceAs(originalHead);
402	      assertThat(accessQueueSize(cache)).isEqualTo(cache.size());
403	    }
404	  }
405	
406	  /** Warms the given cache by getting all values in {@code [start, end)}, in order. */
407	  static void warmUp(LoadingCache<Integer, Integer> map, int start, int end) {
408	    checkNotNull(map);
409	    for (int i = start; i < end; i++) {
410	      map.getUnchecked(i);
411	    }
412	  }
413	
414	  static void expireEntries(Cache<?, ?> cache, long expiringTime, FakeTicker ticker) {
415	    checkNotNull(ticker);
416	    expireEntries(toLocalCache(cache), expiringTime, ticker);
417	  }
418	
419	  static void expireEntries(LocalCache<?, ?> cchm, long expiringTime, FakeTicker ticker) {
420	
421	    for (Segment<?, ?> segment : cchm.segments) {
422	      drainRecencyQueue(segment);
423	    }
424	
425	    ticker.advance(2 * expiringTime, MILLISECONDS);
426	
427	    long now = ticker.read();
428	    for (Segment<?, ?> segment : cchm.segments) {
429	      expireEntries(segment, now);
430	      assertWithMessage("Expiration queue must be empty by now")
431	          .that(writeQueueSize(segment))
432	          .isEqualTo(0);
433	      assertWithMessage("Expiration queue must be empty by now")
434	          .that(accessQueueSize(segment))
435	          .isEqualTo(0);
436	      assertWithMessage("Segments must be empty by now").that(segmentSize(segment)).isEqualTo(0);
437	    }
438	    cchm.processPendingNotifications();
439	  }
440	
441	  static void expireEntries(Segment<?, ?> segment, long now) {
442	    segment.lock();
443	    try {
444	      segment.expireEntries(now);
445	      segment.cleanUp();
446	    } finally {
447	      segment.unlock();
448	    }
449	  }
450	
451	  static void checkEmpty(Cache<?, ?> cache) {
452	    assertThat(cache.size()).isEqualTo(0);
453	    assertThat(cache.asMap().containsKey(null)).isFalse();
454	    assertThat(cache.asMap().containsKey(6)).isFalse();
455	    assertThat(cache.asMap().containsValue(null)).isFalse();
456	    assertThat(cache.asMap().containsValue(6)).isFalse();
457	    checkEmpty(cache.asMap());
458	  }
459	
460	  static void checkEmpty(ConcurrentMap<?, ?> map) {
461	    checkEmpty(map.keySet());
462	    checkEmpty(map.values());
463	    checkEmpty(map.entrySet());
464	    assertThat(map).isEqualTo(ImmutableMap.of());
465	    assertThat(map.hashCode()).isEqualTo(ImmutableMap.of().hashCode());
466	    assertThat(map.toString()).isEqualTo(ImmutableMap.of().toString());
467	
468	    if (map instanceof LocalCache) {
469	      LocalCache<?, ?> cchm = (LocalCache<?, ?>) map;
470	
471	      checkValidState(cchm);
472	      assertThat(cchm.isEmpty()).isTrue();
473	      assertThat(cchm).isEmpty();
474	      for (LocalCache.Segment<?, ?> segment : cchm.segments) {
475	        assertThat(segment.count).isEqualTo(0);
476	        assertThat(segmentSize(segment)).isEqualTo(0);
477	        assertThat(segment.writeQueue.isEmpty()).isTrue();
478	        assertThat(segment.accessQueue.isEmpty()).isTrue();
479	      }
480	    }
481	  }
482	
483	  static void checkEmpty(Collection<?> collection) {
484	    assertThat(collection.isEmpty()).isTrue();
485	    assertThat(collection).isEmpty();
486	    assertThat(collection.iterator().hasNext()).isFalse();
487	    assertThat(collection.toArray()).isEmpty();
488	    assertThat(collection.toArray(new Object[0])).isEmpty();
489	    if (collection instanceof Set) {
490	      new EqualsTester()
491	          .addEqualityGroup(ImmutableSet.of(), collection)
492	          .addEqualityGroup(ImmutableSet.of(""))
493	          .testEquals();
494	    } else if (collection instanceof List) {
495	      new EqualsTester()
496	          .addEqualityGroup(ImmutableList.of(), collection)
497	          .addEqualityGroup(ImmutableList.of(""))
498	          .testEquals();
499	    }
500	  }
501	
502	  private CacheTesting() {}
503	}
